#!/usr/bin/env python3
"""Codex SessionStart hook — inject latest unconsumed answer as additionalContext.

Scans answers/ for a q_*.json file matching the current session_id that has NOT
been consumed (no .consumed.json counterpart). If found, injects the answer summary
so Codex can continue from where the human left off.

Note: this adds one new Codex turn. Strictly inferior to Claude's native defer path,
but it's the best available workaround for Codex CLI.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

_HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(_HERE.parent))

from lib.core import HANDOFF_ROOT, append_audit, read_json


def emit(obj: dict) -> None:
    sys.stdout.write(json.dumps(obj))
    sys.stdout.flush()


def latest_unconsumed_answer(root: Path, session_id: str) -> dict | None:
    answers_dir = root / "answers"
    if not answers_dir.exists():
        return None
    consumed = {p.name.replace(".consumed.json", ".json") for p in answers_dir.glob("q_*.consumed.json")}
    for p in sorted(answers_dir.glob("q_*.json")):
        if p.name in consumed or ".consumed" in p.name:
            continue
        ans = read_json(p)
        if ans and ans.get("session_id") == session_id:
            return ans
    return None


def main() -> int:
    raw = sys.stdin.read()
    try:
        event = json.loads(raw) if raw.strip() else {}
    except json.JSONDecodeError:
        emit({})
        return 0

    session_id: str = event.get("session_id") or ""
    if not session_id:
        emit({})
        return 0

    root = HANDOFF_ROOT
    answer = latest_unconsumed_answer(root, session_id)
    if not answer:
        emit({})
        return 0

    qid = answer.get("question_id", "unknown")
    answers_list = answer.get("answers", [])
    answers_text = "; ".join(
        str(a.get("answer", a)) if isinstance(a, dict) else str(a)
        for a in answers_list
    )
    notes = answer.get("notes", "")
    context = f"Human answered pending question {qid}: {answers_text}."
    if notes:
        context += f" Notes: {notes}"
    context += " Continue from that answer."

    append_audit("answer_injected_codex", question_id=qid, session_id=session_id)

    emit({
        "hookSpecificOutput": {
            "hookEventName": "SessionStart",
            "additionalContext": context,
        }
    })
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Merge agent-handoff hooks into Codex hooks.json.

Default target: ~/.codex/hooks.json (global).
Never overwrites — appends only missing entries. Backs up first.

Usage:
    python scripts/merge_codex.py                     # global ~/.codex/hooks.json
    python scripts/merge_codex.py --target /path/to/hooks.json
    python scripts/merge_codex.py --dry-run
"""
from __future__ import annotations

import argparse
import json
import os
import shutil
import sys
import tempfile
from pathlib import Path

_REPO = Path(__file__).resolve().parent.parent


def _codex_hooks() -> dict:
    repo_posix = _REPO.as_posix()
    return {
        "Stop": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": f"python {repo_posix}/codex/stop_gate.py",
                        "timeout": 30,
                    }
                ]
            }
        ],
        "SessionStart": [
            {
                "matcher": "startup|resume",
                "hooks": [
                    {
                        "type": "command",
                        "command": f"python {repo_posix}/codex/session_start.py",
                        "timeout": 10,
                    }
                ]
            }
        ],
    }


def _existing_commands(entries: list[dict]) -> set[str]:
    cmds: set[str] = set()
    for entry in entries:
        for h in entry.get("hooks", []):
            cmd = h.get("command", "")
            if cmd:
                cmds.add(cmd)
    return cmds


def merge_hooks(existing: dict, additions: dict) -> tuple[dict, list[str]]:
    result: dict = dict(existing)
    added: list[str] = []
    for event, new_entries in additions.items():
        if event not in result:
            result[event] = list(new_entries)
            for entry in new_entries:
                for h in entry.get("hooks", []):
                    added.append(f"{event}/{h.get('command', '?')}")
        else:
            existing_cmds = _existing_commands(result[event])
            for entry in new_entries:
                entry_cmds = {h.get("command", "") for h in entry.get("hooks", [])}
                if not entry_cmds.intersection(existing_cmds):
                    result[event].append(entry)
                    for cmd in entry_cmds:
                        added.append(f"{event}/{cmd}")
    return result, added


def merge_into(settings_path: Path, dry_run: bool = False) -> int:
    settings_path.parent.mkdir(parents=True, exist_ok=True)

    if settings_path.exists():
        try:
            current = json.loads(settings_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            print(f"warning: {settings_path} invalid JSON, treating as empty", file=sys.stderr)
            current = {}
    else:
        current = {}

    current.setdefault("hooks", {})
    merged_hooks, added = merge_hooks(current["hooks"], _codex_hooks())
    current["hooks"] = merged_hooks

    if not added:
        print(f"nothing to add - hooks already present in {settings_path}")
        return 0

    if dry_run:
        print(f"[dry-run] would write {settings_path}:")
        print(json.dumps(current, indent=2))
        print(f"\nwould add: {added}")
        return 0

    if settings_path.exists():
        bak = settings_path.with_suffix(".json.bak")
        shutil.copy2(str(settings_path), str(bak))
        print(f"backed up -> {bak}")

    with tempfile.NamedTemporaryFile(
        mode="w", suffix=".tmp", dir=settings_path.parent, delete=False, encoding="utf-8"
    ) as f:
        json.dump(current, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
        tmp = f.name
    os.replace(tmp, str(settings_path))

    print(f"merged -> {settings_path}")
    for item in added:
        print(f"  + {item}")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description="Merge agent-handoff hooks into Codex hooks.json")
    ap.add_argument("--target", help="Explicit hooks.json path (default: ~/.codex/hooks.json)")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()

    if args.target:
        settings_path = Path(args.target)
    else:
        settings_path = Path.home() / ".codex" / "hooks.json"

    return merge_into(settings_path, dry_run=args.dry_run)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Merge agent-handoff hooks into an existing .claude/settings.json.

Does NOT overwrite — appends only the hook entries not already present.
Backs up existing file to settings.json.bak before writing.

Usage:
    python scripts/merge_settings.py                      # target: cwd/.claude/settings.json
    python scripts/merge_settings.py --target /repo/path  # target repo
    python scripts/merge_settings.py --global             # ~/.claude/settings.json
    python scripts/merge_settings.py --dry-run            # print result, don't write
"""
from __future__ import annotations

import argparse
import json
import os
import sys
import tempfile
from pathlib import Path

_REPO = Path(__file__).resolve().parent.parent


def _handoff_hooks(mode: str = "defer") -> dict:
    """Build hook config.

    mode='defer'  : end-turn + resume via watcher (pretool_ask.py)
    mode='block'  : same-turn blocking pause (pretool_ask_block.py, timeout 7200s)
    """
    repo_posix = _REPO.as_posix()
    if mode == "block":
        pretool_cmd = f"python {repo_posix}/claude/pretool_ask_block.py"
        pretool_entry = {"type": "command", "command": pretool_cmd, "timeout": 7200}
    else:
        pretool_cmd = f"python {repo_posix}/claude/pretool_ask.py"
        pretool_entry = {"type": "command", "command": pretool_cmd}
    return {
        "PreToolUse": [
            {
                "matcher": "AskUserQuestion",
                "hooks": [pretool_entry],
            }
        ],
        "Notification": [
            {
                "matcher": "permission_prompt|idle_prompt",
                "hooks": [
                    {
                        "type": "command",
                        "command": f"python {repo_posix}/scripts/notify.py",
                    }
                ],
            }
        ],
    }


def _existing_commands(entries: list[dict]) -> set[str]:
    cmds: set[str] = set()
    for entry in entries:
        for h in entry.get("hooks", []):
            cmd = h.get("command", "")
            if cmd:
                cmds.add(cmd)
    return cmds


def merge_hooks(existing: dict, additions: dict) -> tuple[dict, list[str]]:
    """Merge additions into existing hooks block.

    Returns (merged_hooks, list_of_added_descriptions).
    Skips entries whose command string is already present.
    """
    result: dict = dict(existing)
    added: list[str] = []
    for event, new_entries in additions.items():
        if event not in result:
            result[event] = list(new_entries)
            for entry in new_entries:
                for h in entry.get("hooks", []):
                    added.append(f"{event}/{h.get('command', '?')}")
        else:
            existing_cmds = _existing_commands(result[event])
            for entry in new_entries:
                entry_cmds = {h.get("command", "") for h in entry.get("hooks", [])}
                if not entry_cmds.intersection(existing_cmds):
                    result[event].append(entry)
                    for cmd in entry_cmds:
                        added.append(f"{event}/{cmd}")
    return result, added


def merge_into(settings_path: Path, dry_run: bool = False) -> int:
    settings_path.parent.mkdir(parents=True, exist_ok=True)

    if settings_path.exists():
        try:
            current = json.loads(settings_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            print(f"warning: {settings_path} is invalid JSON — treating as empty", file=sys.stderr)
            current = {}
    else:
        current = {}

    current.setdefault("hooks", {})
    merged_hooks, added = merge_hooks(current["hooks"], _handoff_hooks(mode=_MODE))
    current["hooks"] = merged_hooks

    if not added:
        print(f"nothing to add — hooks already present in {settings_path}")
        return 0

    if dry_run:
        print(f"[dry-run] would write {settings_path}:")
        print(json.dumps(current, indent=2))
        print(f"\nwould add: {added}")
        return 0

    # backup
    if settings_path.exists():
        bak = settings_path.with_suffix(".json.bak")
        import shutil
        shutil.copy2(str(settings_path), str(bak))
        print(f"backed up -> {bak}")

    # atomic write
    with tempfile.NamedTemporaryFile(
        mode="w", suffix=".tmp", dir=settings_path.parent, delete=False, encoding="utf-8"
    ) as f:
        json.dump(current, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
        tmp = f.name
    os.replace(tmp, str(settings_path))

    print(f"merged -> {settings_path}")
    for item in added:
        print(f"  + {item}")
    return 0


_MODE = "defer"


def main() -> int:
    global _MODE
    ap = argparse.ArgumentParser(description="Merge agent-handoff hooks into .claude/settings.json")
    ap.add_argument("--target", help="Path to target repo (default: cwd)")
    ap.add_argument("--global", dest="global_", action="store_true",
                    help="Merge into global ~/.claude/settings.json")
    ap.add_argument("--dry-run", action="store_true", help="Print result without writing")
    ap.add_argument("--mode", choices=["defer", "block"], default="defer",
                    help="defer=end turn + watcher resume; block=same-turn pause (default: defer)")
    args = ap.parse_args()

    _MODE = args.mode

    if args.global_:
        settings_path = Path.home() / ".claude" / "settings.json"
    elif args.target:
        settings_path = Path(args.target) / ".claude" / "settings.json"
    else:
        settings_path = Path.cwd() / ".claude" / "settings.json"

    return merge_into(settings_path, dry_run=args.dry_run)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Provider-agnostic notification fan-out.

Reads NOTIFY_TARGETS env and dispatches to enabled channels.
Payload carries question_id + short summary ONLY. Never raw prompts or secrets.

PHASE 0 STUB. Real urllib/requests calls land in Phase 2.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import urllib.request
from pathlib import Path

HANDOFF_ROOT = Path(__file__).resolve().parent.parent


def load_env() -> dict[str, str]:
    env_path = HANDOFF_ROOT / ".env"
    out = dict(os.environ)
    if env_path.exists():
        for line in env_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line:
                continue
            k, _, v = line.partition("=")
            out.setdefault(k.strip(), v.strip())
    return out


def send_ntfy(env: dict, payload: dict) -> bool:
    url = env.get("NTFY_URL", "").strip()
    if not url or "REPLACE-ME" in url:
        return False
    req = urllib.request.Request(
        url,
        data=payload["summary"].encode("utf-8"),
        headers={"Title": f"Agent blocked: {payload['question_id']}"},
        method="POST",
    )
    try:
        urllib.request.urlopen(req, timeout=5).read()
        return True
    except Exception as e:
        print(f"ntfy failed: {e}", file=sys.stderr)
        return False


def send_telegram(env: dict, payload: dict) -> bool:
    token = env.get("TELEGRAM_BOT_TOKEN", "").strip()
    chat = env.get("TELEGRAM_CHAT_ID", "").strip()
    if not token or not chat:
        return False
    url = f"https://api.telegram.org/bot{token}/sendMessage"
    body = json.dumps({
        "chat_id": chat,
        "text": f"Agent blocked: {payload['question_id']}\n{payload['summary']}",
        "reply_markup": {
            "force_reply": True,
            "selective": True,
            "input_field_placeholder": "Reply with the answer",
        },
    }).encode("utf-8")
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"}, method="POST")
    try:
        urllib.request.urlopen(req, timeout=5).read()
        return True
    except Exception as e:
        print(f"telegram failed: {e}", file=sys.stderr)
        return False


def send_slack(env: dict, payload: dict) -> bool:
    url = env.get("SLACK_WEBHOOK_URL", "").strip()
    if not url:
        return False
    body = json.dumps({"text": f"{payload['question_id']}: {payload['summary']}"}).encode("utf-8")
    req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"}, method="POST")
    try:
        urllib.request.urlopen(req, timeout=5).read()
        return True
    except Exception as e:
        print(f"slack failed: {e}", file=sys.stderr)
        return False


def send_burnttoast(env: dict, payload: dict) -> bool:
    if env.get("BURNTTOAST_ENABLED", "0") != "1":
        return False
    ps = (
        "Import-Module BurntToast -ErrorAction SilentlyContinue; "
        f"New-BurntToastNotification -Text 'Agent blocked', '{payload['question_id']}: {payload['summary']}'"
    )
    try:
        subprocess.run(["powershell.exe", "-NoProfile", "-Command", ps], timeout=10, check=False)
        return True
    except Exception as e:
        print(f"burnttoast failed: {e}", file=sys.stderr)
        return False


CHANNELS = {
    "ntfy": send_ntfy,
    "telegram": send_telegram,
    "slack": send_slack,
    "burnttoast": send_burnttoast,
}


def main() -> int:
    env = load_env()

    # Hook-mode: read JSON from stdin and build payload
    payload = {
        "question_id": env.get("QUESTION_ID", "unknown"),
        "summary": env.get("QUESTION_SUMMARY", "Agent needs input"),
    }
    try:
        data = sys.stdin.read()
        if data:
            evt = json.loads(data)
            payload["question_id"] = evt.get("question_id", payload["question_id"])
            payload["summary"] = evt.get("message") or evt.get("summary") or payload["summary"]
    except Exception:
        pass

    targets = [t.strip() for t in env.get("NOTIFY_TARGETS", "ntfy").split(",") if t.strip()]
    results = {}
    for t in targets:
        fn = CHANNELS.get(t)
        if not fn:
            continue
        results[t] = fn(env, payload)

    print(json.dumps({"notify_results": results}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Poll Telegram replies and write answers/q_<id>.json.

This is an inbound edge adapter only. It validates Telegram update metadata,
extracts a question id, writes the normal answer file, and lets the existing
Claude/Codex resume paths consume it.
"""
from __future__ import annotations

import argparse
import json
import sys
import time
import urllib.parse
import urllib.request
from pathlib import Path

_HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(_HERE.parent))

from lib.core import (
    HANDOFF_ROOT,
    append_audit,
    atomic_write_json,
    is_valid_question_id,
    load_env,
    read_json,
    read_question,
    write_answer,
)


def _state_path(root: Path) -> Path:
    return root / "state" / "telegram_ingest.json"


def load_offset(root: Path) -> int:
    state = read_json(_state_path(root)) or {}
    try:
        return int(state.get("last_update_id", 0))
    except Exception:
        return 0


def save_offset(root: Path, update_id: int) -> None:
    atomic_write_json(_state_path(root), {
        "last_update_id": update_id,
        "updated_at_unix": int(time.time()),
    })


def fetch_updates(token: str, offset: int, timeout: int = 3) -> list[dict]:
    query = urllib.parse.urlencode({
        "offset": offset,
        "timeout": timeout,
        "allowed_updates": json.dumps(["message"]),
    })
    url = f"https://api.telegram.org/bot{token}/getUpdates?{query}"
    req = urllib.request.Request(url, method="GET")
    with urllib.request.urlopen(req, timeout=timeout + 5) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    if not data.get("ok"):
        raise RuntimeError("telegram getUpdates returned ok=false")
    return data.get("result", [])


def extract_question_id(message: dict) -> tuple[str | None, str]:
    text = (message.get("text") or "").strip()
    reply = message.get("reply_to_message") or {}
    reply_text = (reply.get("text") or "").strip()

    for token in reply_text.replace("\n", " ").split():
        clean = token.strip("`.,:;()[]")
        if is_valid_question_id(clean):
            return clean, text

    if text:
        first, _, rest = text.partition(" ")
        clean = first.strip("`.,:;()[]")
        if is_valid_question_id(clean):
            return clean, rest.strip()

    return None, text


def _matches_allowed_user(message: dict, allowed_user_id: str) -> bool:
    if not allowed_user_id:
        return True
    sender = message.get("from") or {}
    return str(sender.get("id", "")) == allowed_user_id


def process_update(root: Path, env: dict, update: dict) -> bool:
    update_id = update.get("update_id")
    message = update.get("message") or {}
    chat = message.get("chat") or {}
    expected_chat = env.get("TELEGRAM_CHAT_ID", "").strip()
    allowed_user = env.get("TELEGRAM_ALLOWED_USER_ID", "").strip()

    if expected_chat and str(chat.get("id", "")) != expected_chat:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, reason="wrong_chat")
        return False
    if not _matches_allowed_user(message, allowed_user):
        append_audit("telegram_update_ignored", root=root, update_id=update_id, reason="wrong_user")
        return False

    question_id, answer_text = extract_question_id(message)
    if not question_id:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, reason="missing_question_id")
        return False
    if not answer_text:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, question_id=question_id, reason="empty_answer")
        return False

    question = read_question(root, question_id)
    if not question:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, question_id=question_id, reason="question_not_found")
        return False

    try:
        path = write_answer(
            root,
            question,
            answer_text,
            "telegram",
            {
                "update_id": update_id,
                "message_id": message.get("message_id"),
            },
        )
    except FileExistsError:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, question_id=question_id, reason="answer_exists")
        return False
    except Exception as exc:
        append_audit("telegram_update_ignored", root=root, update_id=update_id, question_id=question_id, reason=type(exc).__name__)
        return False

    append_audit(
        "telegram_answer_written",
        root=root,
        question_id=question_id,
        update_id=update_id,
        message_id=message.get("message_id"),
        answer_file=path.name,
    )
    return True


def poll_once(root: Path, env: dict) -> int:
    enabled = env.get("HANDOFF_TELEGRAM_INGEST_ENABLED", "1").strip().lower()
    if enabled in {"0", "false", "no", "off"}:
        print("telegram ingest disabled by HANDOFF_TELEGRAM_INGEST_ENABLED", file=sys.stderr)
        return 0

    token = env.get("TELEGRAM_BOT_TOKEN", "").strip()
    chat = env.get("TELEGRAM_CHAT_ID", "").strip()
    if not token or not chat:
        print("telegram ingest skipped: TELEGRAM_BOT_TOKEN or TELEGRAM_CHAT_ID missing", file=sys.stderr)
        return 0

    last = load_offset(root)
    updates = fetch_updates(token, last + 1)
    written = 0
    for update in updates:
        update_id = int(update.get("update_id", 0))
        try:
            if process_update(root, env, update):
                written += 1
        finally:
            if update_id:
                save_offset(root, update_id)
    return written


def watch(root: Path, env: dict) -> int:
    interval = int(env.get("HANDOFF_TELEGRAM_POLL_INTERVAL", "5"))
    print(f"watching Telegram replies every {interval}s")
    while True:
        try:
            poll_once(root, env)
        except Exception as exc:
            print(f"telegram ingest error: {exc}", file=sys.stderr)
        time.sleep(interval)


def main() -> int:
    ap = argparse.ArgumentParser(description="Poll Telegram replies into answers/q_<id>.json.")
    ap.add_argument("--once", action="store_true", help="poll Telegram once and exit")
    ap.add_argument("--watch", action="store_true", help="poll Telegram forever")
    args = ap.parse_args()

    root = HANDOFF_ROOT
    env = load_env(root)
    if args.watch:
        return watch(root, env)
    poll_once(root, env)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Integration tests for hook scripts via subprocess (no real Claude/Codex needed)."""
from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

_REPO = Path(__file__).resolve().parent.parent
PRETOOL = str(_REPO / "claude" / "pretool_ask.py")
STOPGATE = str(_REPO / "codex" / "stop_gate.py")
SESSION_START = str(_REPO / "codex" / "session_start.py")


def run_hook(script: str, stdin: str, env_extra: dict | None = None) -> dict:
    import os
    env = {**os.environ, "NOTIFY_TARGETS": "", **(env_extra or {})}
    result = subprocess.run(
        [sys.executable, script],
        input=stdin.encode(),
        capture_output=True,
        env=env,
        timeout=10,
    )
    assert result.returncode == 0, result.stderr.decode()
    return json.loads(result.stdout.decode().strip() or "{}")


